//! Phantom Identity repository — PQ public-key storage.
//!
//! Privacy Part 3: the server stores only public keys; secret keys are
//! generated by the client and never sent here.
//!
//! AnyPool conventions: UUIDs and timestamps bound as strings, cast in SQL.
//! Public keys are base64 TEXT (no BYTEA, the Any driver has no codec for it).

use nexus_common::models::phantom::PhantomIdentity;
use sqlx::{AnyPool, Row};
use uuid::Uuid;

use crate::select_cols::PHANTOM_IDENTITY_COLS;

/// Insert a new Phantom identity for a user (public keys only).
///
/// ON CONFLICT DO NOTHING — if the user already has an identity this returns
/// Ok(None); callers decide whether that is an error.
pub async fn insert_identity(
    pool: &AnyPool,
    identity: &PhantomIdentity,
) -> Result<Option<PhantomIdentity>, sqlx::Error> {
    let q = format!(
        "INSERT INTO phantom_identities \
             (user_id, did, kem_public, signing_public, created_at) \
         VALUES ($1::uuid, $2, $3, $4, $5::timestamptz) \
         ON CONFLICT (user_id) DO NOTHING \
         RETURNING {PHANTOM_IDENTITY_COLS}"
    );
    sqlx::query_as::<_, PhantomIdentity>(&q)
        .bind(identity.user_id.to_string())
        .bind(&identity.did)
        .bind(&identity.kem_public)
        .bind(&identity.signing_public)
        .bind(identity.created_at.to_rfc3339())
        .fetch_optional(pool)
        .await
}

/// Get a user's Phantom identity.
pub async fn get_identity(pool: &AnyPool, user_id: Uuid) -> Result<Option<PhantomIdentity>, sqlx::Error> {
    let q = format!(
        "SELECT {PHANTOM_IDENTITY_COLS} FROM phantom_identities WHERE user_id = $1::uuid"
    );
    sqlx::query_as::<_, PhantomIdentity>(&q)
        .bind(user_id.to_string())
        .fetch_optional(pool)
        .await
}

/// Delete a user's Phantom identity.
pub async fn delete_identity(pool: &AnyPool, user_id: Uuid) -> Result<bool, sqlx::Error> {
    let rows = sqlx::query("DELETE FROM phantom_identities WHERE user_id = $1::uuid")
        .bind(user_id.to_string())
        .execute(pool)
        .await?
        .rows_affected();
    Ok(rows > 0)
}
